    [TestMethod]
    public void GenerateSlug_SimpleTitle_MatchesSlugPattern()
    {
        var result = _formatter.GenerateSlug("Hello World");
        StringAssert.Matches(result, new(@"^[a-z0-9]+(-[a-z0-9]+)*$"));
    }

    [TestMethod]
    public void GenerateSlug_SimpleTitle_ReturnsLowercaseSlug()
    {
        var result = _formatter.GenerateSlug("Hello World");
        Assert.AreEqual("hello-world", result);
    }

    [TestMethod]
    public void GenerateSlug_SpecialCharacters_DoesNotStartWithHyphen()
    {
        var result = _formatter.GenerateSlug("  --My Post!  ");
        StringAssert.DoesNotMatch(result, new(@"^-"));
    }

    [TestMethod]
    public void GenerateSlug_SpecialCharacters_DoesNotEndWithHyphen()
    {
        var result = _formatter.GenerateSlug("  --My Post!  ");
        StringAssert.DoesNotMatch(result, new(@"-$"));
    }

    [TestMethod]
    public void GenerateSlug_SpecialCharacters_ReturnsCleanSlug()
    {
        var result = _formatter.GenerateSlug("  --My Post!  ");
        Assert.AreEqual("my-post", result);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void GenerateSlug_WhitespaceTitle_Throws()
    {
        _formatter.GenerateSlug("   ");
    }

    // ── FormatCurrency ─────────────────────────────────────────────

    [TestMethod]
    public void FormatCurrency_DefaultSymbol_StartsWithDollarSign()
    {
        var result = _formatter.FormatCurrency(9.99m);
        StringAssert.StartsWith(result, "$");
    }

    [TestMethod]
    public void FormatCurrency_DefaultSymbol_EndsWithTwoDecimals()
    {
        var result = _formatter.FormatCurrency(9.9m);
        StringAssert.Matches(result, new(@"\.\d{2}$"));
    }

    [TestMethod]
    public void FormatCurrency_CustomSymbol_StartsWithSymbol()
    {
        var result = _formatter.FormatCurrency(100m, "€");
        StringAssert.StartsWith(result, "€");
    }

    [TestMethod]
    public void FormatCurrency_WholeNumber_EndsWithZeroCents()
    {
        var result = _formatter.FormatCurrency(42m);
        StringAssert.EndsWith(result, ".00");
    }

    [TestMethod]
    public void FormatCurrency_NegativeAmount_ContainsMinusSign()
    {
        var result = _formatter.FormatCurrency(-5.50m);
        StringAssert.Contains(result, "-");
    }

    [TestMethod]
    public void FormatCurrency_ReturnsExactFormat()
    {
        var result = _formatter.FormatCurrency(1234.50m, "£");
        Assert.AreEqual("£1234.50", result);
    }
}

